&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are&nbsp;seeking&nbsp;a highly motivated&nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Postdoctoral Researcher&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&nbsp;to explore and develop novel applications of&nbsp;cutting-edge&nbsp;AI/ML technologies on large-scale real-world clinical data.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&quot;335559738&quot;:210,&quot;335559739&quot;:210}&quot;&gt;&nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
