&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;MBBS &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;degree required.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;2–5 years of people leadership experience&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; leading Clinical Terminologists, Medical Coders, Clinical Data Annotators, Clinical Abstractors, or similar healthcare data teams.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&nbsp;&lt;/span&gt;&lt;/li&gt;
